// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: CodeMirror 6 editor for one delulu-smash notebook cell: Python
//          highlighting in Everforest, Jupyter run and Tab keys, the console's own keys (run all,
//          clear outputs, add / delete a cell, go up / down a cell: it has no buttons), and completions fetched
//          from the backend (jedi against the live session namespace). Alt+A: inline chat (inline_edit.jsx).
// Usage: wrapped for Reflex by ui/editor.py (CellEditor).
// ---------------------------------------------------------------------------
import React, { useMemo, useRef } from "react";
import CodeMirror from "@uiw/react-codemirror";
import { python } from "@codemirror/lang-python";
import { acceptCompletion, autocompletion, closeCompletion, startCompletion } from "@codemirror/autocomplete";
import { EditorView, keymap, tooltips } from "@codemirror/view";
import { Prec } from "@codemirror/state";
import { createTheme } from "@uiw/codemirror-themes";
import { tags as t } from "@lezer/highlight";
import { inlineEdit } from "./inline_edit.jsx";

// Everforest dark, medium contrast. Token colors follow everforest.vim's highlight groups,
// the same mapping experimental/textual-kernel's theme.py uses.
export const c = {
  bg1: "#343f44", bg3: "#475258", bg4: "#4f585e", fg: "#d3c6aa", red: "#e67e80", orange: "#e69875",
  yellow: "#dbbc7f", green: "#a7c080", aqua: "#83c092", blue: "#7fbbb3", purple: "#d699b6", grey1: "#859289",
};

// Shared with sql_editor.jsx, which only swaps the token colors.
export const editorSettings = {
  background: "transparent",
  foreground: c.fg,
  caret: c.fg,
  selection: c.bg4,
  selectionMatch: c.bg3,
  lineHighlight: "transparent",
  fontFamily: '"JetBrainsMono Nerd Font", "JetBrains Mono", monospace',
};

const everforest = createTheme({
  theme: "dark",
  settings: editorSettings,
  styles: [
    { tag: [t.keyword, t.controlKeyword, t.moduleKeyword, t.operatorKeyword, t.definitionKeyword], color: c.red, fontStyle: "italic" },
    { tag: [t.string, t.special(t.string)], color: c.green },
    { tag: [t.function(t.variableName), t.function(t.propertyName), t.function(t.definition(t.variableName))], color: c.green },
    { tag: [t.number, t.bool, t.null], color: c.purple },
    { tag: [t.className, t.typeName, t.definition(t.className)], color: c.yellow },
    { tag: [t.operator, t.derefOperator], color: c.orange },
    { tag: [t.comment, t.lineComment], color: c.grey1, fontStyle: "italic" },
    { tag: [t.self, t.standard(t.variableName)], color: c.blue },
    { tag: t.escape, color: c.aqua },
    { tag: t.meta, color: c.orange },
  ],
});

// jedi completion types -> CodeMirror's icon classes
const kinds = { function: "function", class: "class", module: "namespace", keyword: "keyword", property: "property",
  param: "variable", instance: "variable", statement: "variable", path: "text" };

/**
 * Tab, as in Jupyter: accept the open suggestion, or ask for one after a name or dot; anywhere else
 * return false so it indents. Shared with sql_editor.jsx.
 */
export function completeOrIndent(view) {
  if (acceptCompletion(view)) return true;
  const { head, empty } = view.state.selection.main;
  const line = view.state.doc.lineAt(head);
  if (empty && /[\w.]$/.test(line.text.slice(0, head - line.from))) return startCompletion(view);
  return false;
}

// interactionDelay 0: by default CodeMirror ignores Tab/Enter for 75 ms after the popup opens or
// updates, which it does on every keystroke and again when the backend answers, so a Tab typed at
// normal speed fell through and indented instead of completing.
export const completionOptions = { interactionDelay: 0 };

/** Focus the editor of the cell after `node`'s cell; it may not exist yet when the last cell was just run. */
function focusNextCell(node) {
  const cell = node.closest(".cell");
  let tries = 0;
  const timer = setInterval(() => {
    const cells = [...document.querySelectorAll(".cell")];
    const next = cells[cells.indexOf(cell) + 1];
    const target = next && next.querySelector(".cm-content");
    if (target) {
      target.focus();
      clearInterval(timer);
    } else if (++tries > 30) {
      clearInterval(timer);
    }
  }, 100);
}

/** Focus a cell's editor once `find()` gives the cell (it may not be on the page yet); gives up after 3 s. */
function focusWhen(find) {
  let tries = 0;
  const timer = setInterval(() => {
    const cell = find();
    const target = cell && cell.querySelector(".cm-content");
    if (target) {
      target.focus();
      target.scrollIntoView({ block: "nearest" });
      clearInterval(timer);
    } else if (++tries > 30) {
      clearInterval(timer);
    }
  }, 100);
}

const allCells = () => [...document.querySelectorAll(".cell")];

/** Shortcut.CELL_UP / CELL_DOWN: the cursor goes to the cell above (-1) or below (1); it stays at an end. */
function moveCell(view, step) {
  const cells = allCells();
  const target = cells[cells.indexOf(view.dom.closest(".cell")) + step];
  const content = target && target.querySelector(".cm-content");
  if (content) {
    content.focus();
    content.scrollIntoView({ block: "nearest" });
  }
  return true;
}

export function CellEditor({ initialCode, completeUrl, editUrl, token, keys, onRun, onSave, onRunAll, onClearOutputs,
  onAddBelow, onDelete }) {
  // Props change identity on every render; the editor's extensions are built once and read these.
  const live = useRef({});
  live.current = { completeUrl, editUrl, token, onRun, onSave, onRunAll, onClearOutputs, onAddBelow, onDelete };
  const code = useRef(initialCode || "");

  const extensions = useMemo(() => {
    const run = (advance) => (view) => {
      closeCompletion(view); // otherwise the popup lingers over the output
      live.current.onRun(view.state.doc.toString(), advance);
      if (advance) focusNextCell(view.dom);
      return true;
    };

    // -- the console's keys (no buttons): each acts from the cell the cursor is in
    const runAll = (view) => {
      closeCompletion(view);
      // this cell's text is only saved when it loses focus: save it first, so it runs as typed
      live.current.onSave(view.state.doc.toString());
      live.current.onRunAll();
      return true;
    };
    const clearOutputs = () => {
      live.current.onClearOutputs();
      return true;
    };
    const addBelow = (view) => {
      const before = new Set(allCells());
      const cell = view.dom.closest(".cell");
      live.current.onAddBelow();
      // the new cell: the one after this that wasn't there before
      focusWhen(() => {
        const cells = allCells();
        const next = cells[cells.indexOf(cell) + 1];
        return next && !before.has(next) ? next : null;
      });
      return true;
    };
    const deleteCell = (view) => {
      closeCompletion(view);
      const cells = allCells();
      const cell = view.dom.closest(".cell");
      const index = cells.indexOf(cell);
      const neighbour = cells[index - 1] || cells[index + 1];
      live.current.onDelete();
      // once it is gone (not while cells run): the cell above, else below; the last cell is
      // replaced by an empty one
      focusWhen(() => (cell.isConnected ? null : neighbour || allCells()[0]));
      return true;
    };

    const complete = async (context) => {
      const word = context.matchBefore(/[A-Za-z_][\w]*/);
      const afterDot = context.matchBefore(/\.\s*/);
      if (!word && !afterDot && !context.explicit) return null;
      const line = context.state.doc.lineAt(context.pos);
      let items = [];
      try {
        const response = await fetch(live.current.completeUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            token: live.current.token,
            code: context.state.doc.toString(),
            line: line.number,
            column: context.pos - line.from,
          }),
        });
        items = response.ok ? await response.json() : [];
      } catch {
        return null; // backend unreachable: just no popup
      }
      if (context.aborted || !items.length) return null;
      return {
        from: word ? word.from : context.pos,
        options: items.map((item) => ({ label: item.label, type: kinds[item.type] || "variable", detail: item.detail })),
        validFor: /^\w*$/,
      };
    };

    return [
      // Alt+A inline chat (first, so its Tab / Esc win while a proposal is shown)
      inlineEdit(() => ({ url: live.current.editUrl, key: keys?.inlineEdit, language: "python",
        token: live.current.token })),
      python(),
      // Wrap long lines instead of scrolling the cell sideways (which hid the start of every line).
      EditorView.lineWrapping,
      autocompletion({ ...completionOptions, override: [complete] }),
      // Attach popups to the page so the notebook's scroll area can't clip them.
      tooltips({ parent: document.body }),
      Prec.highest(
        keymap.of([
          // keys come from shortcuts.py (Shortcut.COMPLETE / RUN_AND_ADVANCE / RUN), read once at mount.
          // Complete (Tab): completeOrIndent
          { key: keys?.complete || "Tab", run: completeOrIndent },
          { key: keys?.runAndAdvance || "Shift-Enter", run: run(true) },
          { key: keys?.run || "Mod-Enter", run: run(false) },
          // Shortcut.RUN_ALL / CLEAR_OUTPUTS / CELL_BELOW / DELETE_CELL / CELL_UP / CELL_DOWN
          { key: keys?.runAll || "Mod-Shift-Enter", run: runAll },
          { key: keys?.clearOutputs || "Alt-z", run: clearOutputs },
          { key: keys?.cellBelow || "Alt-Enter", run: addBelow },
          { key: keys?.deleteCell || "Alt-Backspace", run: deleteCell },
          { key: keys?.cellUp || "Alt-ArrowUp", run: (view) => moveCell(view, -1) },
          { key: keys?.cellDown || "Alt-ArrowDown", run: (view) => moveCell(view, 1) },
        ]),
      ),
    ];
  }, []);

  return (
    <CodeMirror
      value={initialCode || ""}
      theme={everforest}
      extensions={extensions}
      indentWithTab={true}
      placeholder="python"
      basicSetup={{ lineNumbers: false, foldGutter: false, highlightActiveLine: false, highlightActiveLineGutter: false,
        tabSize: 4 }}
      onChange={(value) => { code.current = value; }}
      onBlur={() => live.current.onSave(code.current)}
    />
  );
}
